KG42.register("rules-49069132dc734b96699def8e",{"id":"23-hierarchical_market_structure::v141-c-R001","paper":"23-hierarchical_market_structure","record":{"rule_id":"v141-c-R001","mechanism_id":"v141-a-M01","name":"Supply submission","process_stage":"bidding","market_meaning":"The microgrid may bid its excess generation in the DNEM. Scope: Microgrid supply submission in the DNEM under the excess-generation policy. Condition: The microgrid adopts the policy of serving local demand and offering excess generation. The microgrid may bid its total generation capacity in the DNEM. Scope: Microgrid supply submission in the DNEM under the total-generation-capacity policy. Condition: The microgrid adopts the alternative policy of serving local demand economically from the distribution network.","independence_rationale":"Relations governed by the approved function bidding.supply under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["bidding.supply"],"E":[],"omega":{"market_type":"DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"bidding","context_text":"Microgrid supply submission in the DNEM under the excess-generation policy. | Microgrid supply submission in the DNEM under the total-generation-capacity policy.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E008"]},"x":[{"variable_id":"v141-c-R001-X-Pm","symbol":"P_m","meaning":"Generation dispatch of microgrid m [MW].","kind":"operational","domain":"generation dispatch quantity for microgrid m; no standalone domain is stated in (4)-(6)","unit":"MW","indices":["m"],"evidence_ids":["v141-b-g01-E000","v141-b-g01-E008"]},{"variable_id":"v141-c-R001-X-Pme","symbol":"P_{me}","meaning":"Generation dispatch of microgrid m in generation dispatch block e; the block quantities sum to P_m by (6).","kind":"operational","domain":"generation dispatch block quantity; no standalone domain is stated in (6), with the block-sum relation \\sum_e P_{me} = P_m","unit":"MW","indices":["m","e"],"evidence_ids":["v141-b-g01-E000","v141-b-g01-E008"]},{"variable_id":"v141-c-R001-X-psim","symbol":"\\psi_m","meaning":"Bidding strategy vector of microgrid m in the DNEM.","kind":"operational","domain":"bounded componentwise by \\underline{\\psi}_m and \\bar{\\psi}_m per (5)","unit":null,"indices":["m"],"evidence_ids":["v141-b-g01-E000","v141-b-g01-E008"]},{"variable_id":"v141-c-R001-X-rhom","symbol":"\\rho_m","meaning":"Bidding vector of microgrid m in the DNEM [$/MW], determined by (6).","kind":"operational","domain":"DNEM bid vector for microgrid m determined by (6)","unit":"$/MW","indices":["m"],"evidence_ids":["v141-b-g01-E000","v141-b-g01-E008"]}],"theta":[{"parameter_id":"v141-c-R001-T-alpham","symbol":"\\alpha_m","meaning":"Coefficient of the quadratic generation-cost function for microgrid m, used in the marginal-cost term of the DNEM bid vector (6).","value":{"kind":"symbolic","number_value":null,"text_value":"symbolic coefficient alpha_m"},"unit":null,"indices":["m"],"evidence_ids":["v141-b-g01-E000","v141-b-g01-E008"]},{"parameter_id":"v141-c-R001-T-betam","symbol":"\\beta_m","meaning":"Coefficient of the generation-cost function for microgrid m, used in the marginal-cost term of the DNEM bid vector (6).","value":{"kind":"symbolic","number_value":null,"text_value":"symbolic coefficient beta_m"},"unit":null,"indices":["m"],"evidence_ids":["v141-b-g01-E000","v141-b-g01-E008"]},{"parameter_id":"v141-c-R001-T-underline-psim","symbol":"\\underline{\\psi}_m","meaning":"Lower limit of the bidding strategy vector of microgrid m in the DNEM.","value":{"kind":"symbolic","number_value":null,"text_value":"symbolic lower limit"},"unit":null,"indices":["m"],"evidence_ids":["v141-b-g01-E000","v141-b-g01-E008"]},{"parameter_id":"v141-c-R001-T-overline-psim","symbol":"\\bar{\\psi}_m","meaning":"Upper limit of the bidding strategy vector of microgrid m in the DNEM.","value":{"kind":"symbolic","number_value":null,"text_value":"symbolic upper limit"},"unit":null,"indices":["m"],"evidence_ids":["v141-b-g01-E000","v141-b-g01-E008"]}],"phi":[{"constraint_id":"v141-c-R001-C001","kind":"procedural","role":"core","statement":"The microgrid may bid its excess generation in the DNEM. Scope: Microgrid supply submission in the DNEM under the excess-generation policy. Condition: The microgrid adopts the policy of serving local demand and offering excess generation.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["bidding.supply"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-E008"]},{"constraint_id":"v141-c-R001-C002","kind":"procedural","role":"core","statement":"The microgrid may bid its total generation capacity in the DNEM. Scope: Microgrid supply submission in the DNEM under the total-generation-capacity policy. Condition: The microgrid adopts the alternative policy of serving local demand economically from the distribution network.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["bidding.supply"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-E008"]},{"constraint_id":"v141-c-R001-C003","kind":"mathematical","role":"core","statement":"In both policies described in C001 and C002, the generation bidding vector of microgrid m in the DNEM is rho_m = psi_m(2 alpha_m P_me + beta_m), with generation dispatch blocks satisfying sum_e P_me = P_m.","expression":"\\rho_m = \\psi_m(2\\alpha_m P_{me} + \\beta_m); \\quad \\sum_e P_{me} = P_m.","formalization_origin":"source","template_id":null,"members":["bidding.supply"],"variable_refs":["v141-c-R001-X-rhom","v141-c-R001-X-psim","v141-c-R001-X-Pme","v141-c-R001-X-Pm"],"parameter_refs":["v141-c-R001-T-alpham","v141-c-R001-T-betam"],"evidence_ids":["v141-b-g01-E008","v141-b-g01-E000"]},{"constraint_id":"v141-c-R001-C004","kind":"mathematical","role":"supporting","statement":"The bidding strategy of microgrid m in the DNEM is bounded between its lower and upper limits.","expression":"\\underline{\\psi}_m \\le \\psi_m \\le \\bar{\\psi}_m","formalization_origin":"source","template_id":null,"members":["bidding.supply"],"variable_refs":["v141-c-R001-X-psim"],"parameter_refs":["v141-c-R001-T-underline-psim","v141-c-R001-T-overline-psim"],"evidence_ids":["v141-b-g01-E008","v141-b-g01-E000"]}],"pi":[{"evidence_id":"v141-b-g01-E008","location":{"location_id":"src-fbc18f73e3-p03-c2r3__v141-a-M01-bidding","page":3,"printed_page":null,"section":"II-B Microgrids Objective","anchor_text":"ds ψ′ ≤ψ′j ≤ψ′j (2) jme- he ρ′j = ψ′j 2αjPje + βj ; Pje = Pj. (3) nd e on B. Microgrids Objective de","equation_id":"(4)-(6)","figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"formula"},"source_text":"Microgrid m maximizes the payoff function (4), subjected to the limitations on the bidding vector as shown in (5). Here, the first term in the payoff function is the revenue of the microgrid and the second term is the generation cost. The generation dispatch of microgrids is provided by curtailing the IL and dispatching the DERs. The microgrid may adopt several policies to serve its demand. One policy is to serve local demand and bid the excess generation in the DNEM while the other is to bid on its total generation capacity in the DNEM and serve the local demand economically from the distribution network. In both cases, the bidding vector for generation in microgrid m is shown in (6)\nR_m = \\max_{P_m,\\psi_m} \\left[ \\lambda_0 \\cdot P_m - \\left(\\alpha_m P_m^2 + \\beta_m P_m + \\gamma_m\\right) \\right] \\tag{4}\n\\underline{\\psi}_m \\le \\psi_m \\le \\bar{\\psi}_m \\tag{5}\n\\rho_m = \\psi_m(2\\alpha_m P_{me} + \\beta_m); \\quad \\sum_e P_{me} = P_m. \\tag{6}"},{"evidence_id":"v141-b-g01-E000","location":{"location_id":"src-fbc18f73e3-p01-c1r4__v141-a-M01-participation","page":1,"printed_page":null,"section":"Nomenclature","anchor_text":"Variables Pj Generation dispatch of generator j [MW]. Pm Generation dispatch of microgrid m [MW]. Pe","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-01.png","occurrence_role":"definition"},"source_text":"P_j Generation dispatch of generator j [MW]. P_m Generation dispatch of microgrid m [MW]. P_l^{exp}, P_l^{imp} Power “exported from”/“imported to” distribution network electricity market (DNEM) by LA l [MW]. R_j Payoff function of GENCO j [$]. R_m Payoff function of microgrid m [$]. R_l, R'_l Payoff function of LA l in the DNEM/wholesale electricity market (WEM) [$]. \\rho_m, \\rho_l Bidding vector of microgrid m/LA l in the DNEM [$/MW]. \\rho'_j, \\rho'_l Bidding vector of GENCO j/LA l in the WEM [$/MW]. \\psi_m, \\psi_l Bidding strategy vector of microgrid m/LA l in the DNEM. \\psi'_j, \\psi'_l Bidding strategy vector of unit j of GENCO i/LA l in the WEM. \\lambda_0, \\lambda'_0, \\lambda_b^{'+}, \\lambda_b^{'-} Lagrange multipliers. B_j^o, B_l^o Set of buses o corresponds to the market participants j and l. \\bar{F}_b, \\underline{F}_b Minimum/maximum limits for power flow in branch b [MW]. P^D Total demand in the distribution network [MW]. P_o^{'D} Demand on bus o in the WEM [MW]. \\bar{P}_l^{exp}, \\underline{P}_l^{exp} Minimum/maximum power exported from the DNEM by LA l [MW]. \\bar{P}_l^{imp}, \\underline{P}_l^{imp} Minimum/maximum power imported to the DNEM by LA l [MW]. \\bar{P}_{(.)}, \\underline{P}_{(.)} Minimum/maximum generation dispatch [MW]. SF_b^o Shift factor of branch b with respect to injection at bus o. \\alpha(.), \\beta(.), \\gamma(.) Coefficients for generation cost function. \\bar{\\psi}(.), \\underline{\\psi}(.) Upper/lower limit of the bidding strategy vector in the DNEM. \\bar{\\psi}'(.), \\underline{\\psi}'(.) Upper/lower limit of the bidding strategy vector in the WEM."}],"field_notes":{"empty_E_reason":"C explicitly supplied only source-backed unary facts for this function; other graph gaps remain reviewable.","empty_x_reason":null,"empty_theta_reason":null},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M01-bidding","v141-a-M01-participation"],"extras":{"decision_anchor":"bidding.supply","graph_fact_supports":[[{"evidence_id":"v141-b-g01-E008","quote":"The microgrid may adopt several policies to serve its demand. One policy is to serve local demand and bid the excess generation in the DNEM"}],[{"evidence_id":"v141-b-g01-E008","quote":"One policy is to serve local demand and bid the excess generation in the DNEM while the other is to bid on its total generation capacity in the DNEM and serve the local demand economically from the distribution network."}]],"C2_formalization":{"graph_sha256":"6e59399844c805040767778f787870ac4bd0136f0a44844a16423f513713ad77","applicability":"formalized","reason":"Formalized the shared DNEM generation bid-vector equation (6) and the bidding-strategy bound (5) for microgrid m. The two policy statements in C001 and C002 remain procedural because the supplied source gives no separate equation distinguishing excess-generation bidding from total-capacity bidding; it states that both cases use the same bidding vector (6). The B evidence used here is unreviewed candidate material and is not claimed to have passed independent source review.","bindings":[{"object_id":"v141-c-R001-X-Pm","node_ids":["bidding.supply"],"edge_ids":[],"rationale":"P_m is the microgrid generation quantity entering the DNEM generation bid vector (6), so it binds to the bidding.supply node."},{"object_id":"v141-c-R001-X-Pme","node_ids":["bidding.supply"],"edge_ids":[],"rationale":"P_{me} is the generation dispatch block quantity summed to P_m in the microgrid DNEM bid-vector equation (6), which belongs to bidding.supply."},{"object_id":"v141-c-R001-X-psim","node_ids":["bidding.supply"],"edge_ids":[],"rationale":"psi_m is the microgrid DNEM bidding strategy used to form the supply bid vector in (6), directly under bidding.supply."},{"object_id":"v141-c-R001-X-rhom","node_ids":["bidding.supply"],"edge_ids":[],"rationale":"rho_m is the microgrid DNEM bidding vector submitted in the market and defined by (6), directly under bidding.supply."},{"object_id":"v141-c-R001-T-alpham","node_ids":["bidding.supply"],"edge_ids":[],"rationale":"alpha_m is a generation-cost coefficient used in the marginal-cost term of the bidding.supply bid-vector equation (6)."},{"object_id":"v141-c-R001-T-betam","node_ids":["bidding.supply"],"edge_ids":[],"rationale":"beta_m is a generation-cost coefficient used in the marginal-cost term of the bidding.supply bid-vector equation (6)."},{"object_id":"v141-c-R001-T-underline-psim","node_ids":["bidding.supply"],"edge_ids":[],"rationale":"The lower bidding-strategy limit bounds the microgrid bid strategy at the bidding.supply node."},{"object_id":"v141-c-R001-T-overline-psim","node_ids":["bidding.supply"],"edge_ids":[],"rationale":"The upper bidding-strategy limit bounds the microgrid bid strategy at the bidding.supply node."},{"object_id":"v141-c-R001-C001","node_ids":["bidding.supply"],"edge_ids":[],"rationale":"This existing procedural policy statement is owned by the microgrid supply-submission node bidding.supply."},{"object_id":"v141-c-R001-C002","node_ids":["bidding.supply"],"edge_ids":[],"rationale":"This existing procedural policy statement is owned by the microgrid supply-submission node bidding.supply."},{"object_id":"v141-c-R001-C003","node_ids":["bidding.supply"],"edge_ids":[],"rationale":"The shared bid-vector equation (6) formalizes how the microgrid's supply bid is constructed at bidding.supply; no additional graph edge is required by the frozen graph."},{"object_id":"v141-c-R001-C004","node_ids":["bidding.supply"],"edge_ids":[],"rationale":"The bidding-strategy bounds constrain the microgrid supply submission at bidding.supply."}],"revision_requests":[]}},"quarantined_references":[]}});
